<script setup lang="ts">
import { computed } from 'vue';
import { api, baseUrl } from '../platform';
import { type Row, formatTime } from '../../../shared/domain';
import { useShop, productCategories, orderStates, orderSettlementLabel, money } from '../../../shared/useShop';
const props = defineProps<{ user: Row | null }>();const emit = defineEmits<{ (event: 'join'): void }>();
const { orders, selected, filter, query, tab, error, message, loading, busy, ordering, orderForm, filtered, load, resetFilters, buy, submitOrder, act } = useShop(() => props.user, api);
const total = computed(() => (selected.value?.priceCents || 0) * Number(orderForm.value.quantity || 0) + (orderForm.value.delivery === 'shipping' ? selected.value?.shippingCents || 0 : 0));
function order(row: Row) { if (props.user?.status !== 'approved') emit('join');else buy(row); }
function action(row: Row, name: string) { uni.showModal({ title: name === 'cancel' ? '取消订单' : '确认已收货', content: name === 'cancel' ? '取消后释放所占库存，请确认。' : '请确认已实际收到商品。', success: result => { if (result.confirm) act(row, name); } }); }
function consent(event: any) { orderForm.value.consent = event.detail.value; }
function delivery(event: any) { orderForm.value.delivery = Number(event.detail.value) === 0 ? 'shipping' : 'pickup'; }
</script>
<template><view><view class="title">家乡好物</view><view class="intro">熟悉的家乡味道，捎一份乡情。</view><view class="notice-line">在线下单 · 人工确认 · 线下结算</view><view v-if="message" role="status" class="notice-line">{{ message }}</view><view v-if="error" role="alert" class="error">{{ error }}<button v-if="!ordering" class="text-button" :disabled="loading || busy" @click="load">重新加载</button></view><view v-if="loading" role="status" class="intro">正在加载商品与订单…</view>
<view v-if="ordering && selected" class="form-page"><button class="text-button" :disabled="busy" @click="ordering = false">← 商品详情</button><view class="form-title">填写订单</view><view class="intro">{{ selected.title }} · {{ selected.specification }}</view><view class="field"><text class="field-label">购买数量（可售{{ selected.stock }}件）</text><input v-model="orderForm.quantity" type="number"/></view><view class="field"><text class="field-label">配送方式</text><picker :range="['快递配送', '到店／活动现场自提']" @change="delivery"><view class="picker-value">{{ orderForm.delivery === 'shipping' ? '快递配送' : '自提' }} ▾</view></picker></view><view class="field"><text class="field-label">联系人</text><input v-model="orderForm.name" maxlength="30"/></view><view class="field"><text class="field-label">联系电话</text><input v-model="orderForm.phone" type="number" maxlength="11"/></view><view v-if="orderForm.delivery === 'shipping'" class="field"><text class="field-label">收货地址</text><textarea v-model="orderForm.address" maxlength="300"/></view><view v-else class="safe-note">自提时间与地点由卖家确认后告知，请留意订单信息。</view><view class="order-total">预计合计 <text>{{ money(total) }}</text><view class="meta">含运费 {{ money(orderForm.delivery === 'shipping' ? selected.shippingCents : 0) }}</view></view><view class="switch-row"><text>我确认商品与售后说明，知悉人工确认、线下结算；收货信息仅用于履约。</text><switch :checked="orderForm.consent" @change="consent"/></view><button class="primary" :disabled="busy" @click="submitOrder">{{ busy ? '正在提交订单…' : '提交订单 · 待人工确认' }}</button></view>
<view v-else-if="selected"><button class="text-button" @click="selected = null">← 全部特产</button><swiper v-if="selected.images.length" class="product-swiper" indicator-dots><swiper-item v-for="id in selected.images" :key="id"><image :src="baseUrl() + '/media/' + id" mode="aspectFill"/></swiper-item></swiper><view class="panel"><text class="tag">{{ selected.category }}</text><view class="card-title">{{ selected.title }}</view><view class="meta">{{ selected.specification }} · {{ selected.origin }}</view><view class="price">{{ money(selected.priceCents) }}</view><view class="meta">可售 {{ selected.stock }} 件 · 运费 {{ money(selected.shippingCents) }}／单</view><button class="primary" :disabled="selected.stock < 1 || selected.status !== 'published'" @click="order(selected)">{{ selected.stock > 0 ? '填写订单' : '暂时售罄' }}</button><view class="product-copy prose">{{ selected.description }}</view><view class="card-title">供货与售后</view><view class="meta">{{ selected.seller }} · {{ selected.sellerContact }}</view><view class="prose">{{ selected.afterSales }}</view></view></view>
<template v-else><view class="pill-row shop-tabs"><text :class="['pill', { active: tab === 'products' }]" @click="tab = 'products'">家乡特产</text><text :class="['pill', { active: tab === 'orders' }]" @click="user?.status === 'approved' ? tab = 'orders' : emit('join')">我的订单</text></view><template v-if="tab === 'products'"><input v-model="query" class="search" placeholder="搜索家乡味道、产地"/><view class="pill-row"><text v-for="item in ['全部', ...productCategories]" :key="item" :class="['pill', { active: filter === item }]" @click="filter = item">{{ item }}</text></view><view v-if="!loading && !error && !filtered.length" class="empty"><template v-if="query.trim() || filter !== '全部'">没有找到符合条件的商品。<button class="outline" @click="resetFilters">清除筛选</button></template><template v-else>家乡好物正在准备中<br/>欢迎常来看看</template></view><view class="product-grid"><view v-for="row in filtered" :key="row.id" class="product-card" @click="selected = row"><image v-if="row.images.length" :src="baseUrl() + '/media/' + row.images[0]" mode="aspectFill" lazy-load/><view><text class="product-origin">{{ row.origin }}</text><view>{{ row.title }}</view><text class="product-spec">{{ row.specification }}</text><view class="price">{{ money(row.priceCents) }}</view><text class="product-spec">库存 {{ row.stock }}</text></view></view></view></template><template v-else><view v-if="!loading && !error && !orders.length" class="empty">还没有订单。<button class="outline" @click="tab = 'products'">去逛家乡特产</button></view><view v-for="row in orders" :key="row.id" class="panel"><view class="row"><text class="tag">{{ orderStates[row.status] }}</text><text class="meta">{{ formatTime(row.createdAt) }}</text></view><view class="card-title">{{ row.title }} × {{ row.quantity }}</view><view class="meta">{{ row.specification }}</view><view class="price">{{ money(row.totalCents) }}</view><view class="settlement-label">{{ orderSettlementLabel(row) }}</view><view class="meta">{{ row.orderNo }}</view><view class="prose">{{ row.name }} · {{ row.phone }}<br/>{{ row.delivery === 'shipping' ? row.address : '自提' }}</view><view v-if="row.fulfillment" class="notice-line">{{ row.fulfillment }}</view><view class="meta">卖家：{{ row.seller }} · {{ row.sellerContact }}</view><view class="button-row"><button v-if="['pending','confirmed'].includes(row.status) && row.settlement !== 'confirmed'" class="outline small" :disabled="busy" @click="action(row,'cancel')">取消订单</button><button v-if="['shipped','ready'].includes(row.status)" class="primary small" :disabled="busy" @click="action(row,'receive')">确认已收货</button></view></view></template></template></view></template>
<style scoped>.shop-tabs{margin-top:30rpx}.product-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20rpx}.product-card{background:#fffefa;border:1px solid #e7dfcf;border-radius:24rpx;overflow:hidden}.product-card>image{width:100%;height:280rpx}.product-card>view{padding:24rpx}.product-card>view>view:not(.price){font-size:29rpx;font-weight:600;line-height:1.6;margin:10rpx 0}.product-origin,.product-spec{font-size:21rpx;color:#8e947d;display:block;line-height:1.7}.price{font:44rpx Georgia,serif;color:#a97b40;margin:18rpx 0}.product-swiper{height:550rpx;border-radius:30rpx;overflow:hidden;margin:25rpx 0}.product-swiper image{width:100%;height:100%}.product-copy{margin:35rpx 0;white-space:pre-wrap}.order-total{padding:28rpx 0;border-top:1px solid #e4dcc9;font-size:28rpx}.order-total>text{font-size:45rpx;color:#a97b40}.settlement-label{font-size:24rpx;color:#a17e43;margin:15rpx 0}.product-grid+.safe-note{margin-top:35rpx}</style>
